-- Quranically V1.6: Prophetic Medicine symptom/question dossiers with primary and clinical sources.
-- No treatments, dosage protocols, individual medical advice or false cure claims. Expert clinical and scholarly review pending.
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('honey-for-cough-evidence','honey-for-cough-evidence','Honey and Cough: Prophetic Tradition and Clinical Evidence','العسل والسعال','Traditional sources, current evidence and safety limits','prophetic_medicine','concept','The Qur’an refers to healing in relation to what bees produce (16:69), and Sahih al-Bukhari contains reports about honey in other contexts, including an abdominal complaint. These passages do not document a specific Prophetic prescription for every cough. NHS guidance discusses honey as a possible soothing measure for an ordinary cough but warns never to give honey to babies under one year.','Religious and modern health evidence explained separately.','honey for cough,honey cough,cough and honey,how to use honey for cough,prophetic medicine honey for cough,honey remedy cough,does honey cure cough','Independent medical and qualified Islamic scholarly review pending.','editorial_draft','published','80');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('honey-for-cough-evidence-s1','honey-for-cough-evidence','The Qur’anic and Hadith context','scripture','Surah An-Nahl 16:69 refers to what emerges from the bodies of bees and mentions healing. Sahih al-Bukhari 5684 records an account involving honey and a person with an abdominal complaint. These are genuine primary-source references, but the Hadith is about that reported situation, not an authenticated universal dose or treatment for coughing.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('honey-for-cough-evidence-s2','honey-for-cough-evidence','What contemporary medicine says','science','The NHS explains that a warm honey-and-lemon drink may help soothe an ordinary cough but that the research evidence is limited. Coughs have many causes, including infections, allergies, asthma and other health conditions. A home remedy does not diagnose the cause or guarantee relief.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('honey-for-cough-evidence-s3','honey-for-cough-evidence','Important restrictions','safety','Never give honey to a baby under one year old because of the risk of infant botulism. Honey is sugary and may be unsuitable for some people depending on individual medical needs. Small children must not be given drinks hot enough to burn them. Breathing difficulty, chest pain, blood in sputum or a seriously unwell child requires prompt medical assessment.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('honey-for-cough-evidence-s4','honey-for-cough-evidence','A careful practical understanding','practice','A person may read the cited religious reports for their spiritual and historical meaning while following appropriate clinical guidance for the cause of a cough. No claim that a particular commercial honey cures respiratory disease is justified by this entry, and no dosage for a medical condition is prescribed here.','4');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('honey-for-cough-evidence-r1','honey-for-cough-evidence','quran','The Qur’an — An-Nahl','16:69','https://quran.com/16/69','Bee products and the Qur’anic reference to healing','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('honey-for-cough-evidence-r2','honey-for-cough-evidence','hadith','Sahih al-Bukhari — Medicine','5684','https://sunnah.com/bukhari:5684','Honey in a reported abdominal complaint; not a universal cough protocol','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('honey-for-cough-evidence-r3','honey-for-cough-evidence','clinical','NHS — Cough','Evidence and self-care guidance','https://www.nhs.uk/symptoms/cough/','Limited evidence for soothing cough and appropriate clinical assessment','pending','3');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('honey-for-cough-evidence-r4','honey-for-cough-evidence','clinical','NHS — Foods to avoid in babies','Honey and infant botulism','https://www.nhs.uk/baby/weaning-and-feeding/foods-to-avoid-giving-babies-and-young-children/','Do not offer honey to infants under one year','pending','4');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('hijama-cupping-safety','hijama-cupping-safety','Hijama (Cupping): Reports, Evidence and Safety','الحجامة والسلامة','Historical practice and clinical risks','prophetic_medicine','concept','Cupping is mentioned in authenticated Prophetic medical reports, including Sahih al-Bukhari 5681. Modern cupping practices are not identical in technique or safety. NCCIH distinguishes wet and dry cupping and explains that high-quality evidence for benefits is limited. This article does not recommend a procedure or a specific provider.','Religious and modern health evidence explained separately.','hijama,hijamah,cupping,wet cupping,dry cupping,is hijama safe,hijama safe,what is hijama and is it safe,prophetic cupping safety','Independent medical and qualified Islamic scholarly review pending.','editorial_draft','published','81');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('hijama-cupping-safety-s1','hijama-cupping-safety','What the tradition records','transmission','Sahih al-Bukhari 5681 contains a report mentioning cupping alongside honey and cauterization in a medical context. The report is a historical and religious source; it does not prove that all modern cupping procedures work for all conditions or that an unqualified practitioner can perform them safely.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('hijama-cupping-safety-s2','hijama-cupping-safety','What happens during cupping','overview','The United States National Center for Complementary and Integrative Health describes cupping as the application of suction to the skin using cups. Dry cupping does not pierce the skin. Wet cupping involves breaking the skin and drawing blood, introducing distinct infection-control and blood-exposure risks.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('hijama-cupping-safety-s3','hijama-cupping-safety','Benefits and limits of evidence','science','NCCIH notes that much of the cupping research is low quality. Some pain findings exist, but evidence is not sufficiently strong to establish broad benefits for other conditions. A positive testimonial or religious association is not a controlled clinical demonstration of treatment effectiveness.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('hijama-cupping-safety-s4','hijama-cupping-safety','Potential harm and safer decisions','safety','Cupping can cause skin marks, burns, infection, scars and other complications. Wet cupping adds risks from piercing the skin and contaminated instruments. Do not attempt self-procedures or share cutting instruments. Anyone with medical concerns, a bleeding condition or medications affecting bleeding should discuss the practice with a qualified clinician. Hijama should not replace indicated medical care.','4');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('hijama-cupping-safety-r1','hijama-cupping-safety','hadith','Sahih al-Bukhari — Medicine','5681','https://sunnah.com/bukhari:5681','Cupping in a transmitted treatment-related report','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('hijama-cupping-safety-r2','hijama-cupping-safety','clinical','NIH NCCIH — Cupping','Benefits and safety evidence','https://www.nccih.nih.gov/health/cupping','Cupping definition, uncertain benefits and complications','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('hijama-cupping-safety-r3','hijama-cupping-safety','hadith','Sahih al-Bukhari — Medicine','5683','https://sunnah.com/bukhari:5683','Additional narration mentioning cupping and honey','pending','3');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('asthma-prophetic-medicine-boundaries','asthma-prophetic-medicine-boundaries','Asthma: Prophetic Medicine and the Limits of Cure Claims','الربو والطب النبوي','Responsible treatment and authentic-source boundaries','prophetic_medicine','concept','Asthma is a chronic airway condition that requires medically appropriate management. Qur’anic references to healing and general Prophetic medical reports must not be presented as an authenticated asthma-specific cure. The NIH NCCIH advises against replacing prescribed asthma treatment with complementary approaches. This is an evidence-boundary reference, not a treatment recommendation.','Religious and modern health evidence explained separately.','asthma,asthma cure,cure asthma,does prophetic medicine cure asthma,prophetic medicine asthma,black seed asthma,herbal asthma treatment,breathing illness prophetic remedy','Independent medical and qualified Islamic scholarly review pending.','editorial_draft','published','82');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('asthma-prophetic-medicine-boundaries-s1','asthma-prophetic-medicine-boundaries','First clarify the medical condition','overview','Asthma is a condition affecting the airways that can produce wheezing, coughing and difficulty breathing. Diagnosis, severity, triggers and treatment vary. This entry cannot diagnose asthma, identify its cause in an individual, or provide an inhaler regimen.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('asthma-prophetic-medicine-boundaries-s2','asthma-prophetic-medicine-boundaries','Religious source boundaries','scripture','Qur’an 26:80 attributes healing to Allah in the words of Ibrahim. Sahih al-Bukhari 5681 includes general medical reports involving remedies. Neither of these references identifies a clinically tested, universal asthma cure. An authenticated narration about a substance or treatment does not by itself validate every modern product or disease claim made in its name.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('asthma-prophetic-medicine-boundaries-s3','asthma-prophetic-medicine-boundaries','What medical evidence requires','science','The United States National Center for Complementary and Integrative Health states that evidence does not support substituting complementary approaches for proven asthma treatment. Supplements can have risks or interactions. Research into stress reduction and supportive practices is not evidence that spiritual or herbal methods replace prescribed asthma medicines.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('asthma-prophetic-medicine-boundaries-s4','asthma-prophetic-medicine-boundaries','Safety and when to seek care','safety','Continue clinician-directed treatment and follow an individual asthma action plan where prescribed. Do not stop inhalers or delay assessment because of a traditional remedy claim. Worsening breathing, inability to speak normally, severe distress or symptoms not responding to the prescribed rescue plan require urgent medical attention. For religious questions, a qualified scholar can explain the sources without replacing medical care.','4');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('asthma-prophetic-medicine-boundaries-r1','asthma-prophetic-medicine-boundaries','quran','The Qur’an — Ash-Shuara','26:80','https://quran.com/26/80','Spiritual attribution of healing, not an asthma-specific regimen','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('asthma-prophetic-medicine-boundaries-r2','asthma-prophetic-medicine-boundaries','hadith','Sahih al-Bukhari — Medicine','5681','https://sunnah.com/bukhari:5681','General treatment-related narration, not an asthma protocol','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('asthma-prophetic-medicine-boundaries-r3','asthma-prophetic-medicine-boundaries','clinical','NIH NCCIH — Asthma and Complementary Health Approaches','Safety and evidence summary','https://www.nccih.nih.gov/health/asthma-and-complementary-health-approaches-what-you-need-to-know','Do not replace prescribed asthma care with alternative remedies','pending','3');
